class Timer {
protected:
    void start() { /* ... */ }
    void stop() { /* ... */ }
public:
    virtual void onTimeout() {}
};

// PRIVATE INHERITANCE: Access protected + override virtual
class Task : private Timer {
public:
    void execute() {
        start();  // Access protected member
        // ... work ...
        stop();
    }

    void onTimeout() override {  // Override virtual
        // Custom timeout handling
    }
};

// COMPOSITION: Preferred when no protected access needed
class BetterTask {
    Timer timer;  // Composition: has-a
public:
    void execute() {
        // timer.start();  // ERROR: can't access protected
        // Clearer ownership and lifetime semantics
    }
};

// When to use each:
// Private inheritance: Need protected access or virtual override
// Composition: Default choice for has-a relationships
